Fixpoint anc (f : nat) (st : mstate) (s : aptr) : list aptr :=
  match f with
  | O => []
  | S f' =>
    match s_slots st !! s with
    | None => []
    | Some (m, _) => let b := gbase (MR st m) in b :: (if m_maplen (MR st m) =? 0 then anc f' st b else [])
    end
  end.

