(* [comment removed for export] *)
Lemma zsum_filter_split {A} (w : A -> Z) (f : A -> bool) (l : list A) :
  zsum (map w l) = zsum (map w (List.filter f l)) + zsum (map w (List.filter (fun x => negb (f x)) l)).
Proof.
