Definition CM (K : Z) : Z := 64 * (K + 32) + 32.

Record RES (cs : mstate) (SZ : list (aptr * Z)) (K : Z) : Prop := mkRES {
  rs_einv : EINV cs;
  rs_nlk : NLK cs;
  rs_l63 : L63 cs SZ;
  rs_marith : MARITH cs;
  rs_nmeta : nmeta cs <= CM K
}.

End HMRES.
